            "type": "string"
          },
          "title": "Authors",
          "type": "array"
        }
      },
      "required": [
        "name",
        "authors"
      ],
      "title": "Book",
      "type": "object",
      "additionalProperties": false
    },
    "name": "book",
    "strict": true
  }
}
```

This example defines a schema for a `Book` object with required fields `name` (a string) and `authors` (an array of strings). The `additionalProperties` is set to `false` to disallow any extra fields not defined in the schema, and `strict` is set to `true` to enforce strict adherence to the schema.

